#include <stdio.h>

int main() {
    int temperature = 35;

    if (temperature >= 30) {
        printf("It's hot!\n");
    } else if (temperature >= 20) {
        printf("Nice weather!\n");
    } else {
        printf("It's cold!\n");
    }

    return 0;
}

